import{_ as e,o as r,c as a,a0 as o}from"./chunks/framework.DQOulFGV.js";const g=JSON.parse('{"title":"Pepper❤️Craft 服务器官方文档","description":"","frontmatter":{},"headers":[],"relativePath":"intro.md","filePath":"intro.md"}'),d={name:"intro.md"};function l(n,t,h,p,i,s){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="pepper❤️craft-服务器官方文档" tabindex="-1">Pepper❤️Craft 服务器官方文档 <a class="header-anchor" href="#pepper❤️craft-服务器官方文档" aria-label="Permalink to &quot;Pepper❤️Craft 服务器官方文档&quot;">​</a></h1><blockquote><p>Written by: AtomicalPepper</p></blockquote><p>👋 欢迎来到我们的服务器文档！</p><p>本文档的<strong>大部分内容</strong>只适用于 PepperCraft 服务器，请各位在游玩其他服务器或原版生存时不要过度依赖～</p><h2 id="服务器信息" tabindex="-1">服务器信息 <a class="header-anchor" href="#服务器信息" aria-label="Permalink to &quot;服务器信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>服务器地址</td><td><strong>pepper.ltd</strong></td></tr><tr><td>服务器 QQ 群</td><td><strong>754966689</strong></td></tr><tr><td>官网</td><td><a href="http://web.pepper.ltd" target="_blank" rel="noreferrer">http://web.pepper.ltd</a></td></tr><tr><td>支持版本</td><td><strong>1.21-26.2</strong></td></tr><tr><td>文档开源地址</td><td><a href="https://github.com/nullpepper/PepperServer-Document/" target="_blank" rel="noreferrer">点我点我</a></td></tr></tbody></table><h2 id="参数约定" tabindex="-1">参数约定 <a class="header-anchor" href="#参数约定" aria-label="Permalink to &quot;参数约定&quot;">​</a></h2><p>理解本文档的内容时，你应该了解：</p><ul><li><code>&lt;xxx&gt;</code> 表示<strong>必填参数</strong>。</li><li><code>[xxx]</code> 表示<strong>可选参数</strong>。</li></ul><p>例如：命令 <code>/tpa &lt;玩家名&gt;</code> 意味着你需要将 <code>&lt;玩家名&gt;</code> 替换为一个玩家的游戏名。</p><p>假设你需要对名为 Pepper 的玩家执行命令：</p><table tabindex="0"><thead><tr><th>命令</th><th>正误</th></tr></thead><tbody><tr><td><strong>/tpa Pepper</strong></td><td>✅</td></tr><tr><td>/tpa &lt;Pepper&gt;</td><td>❌</td></tr><tr><td>/tpa &lt;玩家名&gt;</td><td>❌</td></tr></tbody></table><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><p>刚进服务器？跟着这几步五分钟就能开玩：</p><ol><li><strong>绑定 QQ</strong>：输入 <code>/qqbind bind &lt;你的QQ号&gt;</code>，再按提示在 QQ 群内发送验证码（详见 <a href="./qqbind.html">QQ 绑定</a>）。</li><li><strong>认识主城</strong>：出生在主城（安全区，禁止 PvP）。想出发去主世界冒险？输入 <code>/pej</code> 弹射出发；想回城？随时输入 <code>/spawn</code>。</li><li><strong>设置你的家</strong>：在喜欢的位置输入 <code>/sethome</code>，之后无论身处何方，输入 <code>/home</code> 就能回家（详见 <a href="./teleport.html">传送系统</a>）。</li><li><strong>认识经济</strong>：服务器货币是<strong>钻石</strong>，新玩家初始有 8 钻石。用 <code>/money</code> 查看余额，<code>/diamond</code> 打开钻石银行（详见 <a href="./conomy.html">经济系统</a>）。</li><li><strong>开始冒险</strong>：去主世界采集资源、建筑、生存；想找朋友就 <code>/msg &lt;玩家&gt; &lt;内容&gt;</code> 私聊，想传送到朋友身边就 <code>/tpa &lt;玩家&gt;</code>。</li></ol><p>遇到问题？在聊天框输入「回城」「领地」等关键词会收到自动帮助，也可以加入 QQ 群提问。</p><h2 id="文档导航" tabindex="-1">文档导航 <a class="header-anchor" href="#文档导航" aria-label="Permalink to &quot;文档导航&quot;">​</a></h2><ul><li><a href="./quickref.html">常用指令速查</a> —— 一页看完最常用指令</li><li><strong>基础功能</strong>：<a href="./teleport.html">传送系统</a> · <a href="./conomy.html">经济系统</a> · <a href="./chat.html">聊天系统</a> · <a href="./prefix.html">前缀与称号</a> · <a href="./actions.html">休闲动作</a> · <a href="./image.html">图片展示</a> · <a href="./minecart.html">矿车玩法</a></li><li><strong>玩法进阶</strong>：<a href="./worlds.html">世界</a> · <a href="./bedrock.html">基岩版玩家</a> · <a href="./qqbind.html">QQ 绑定</a> · <a href="./special.html">特殊功能</a></li><li><strong>团队玩法</strong>：<a href="./towns/">联盟与领地</a> 系列</li></ul>',18)])])}const f=e(d,[["render",l]]);export{g as __pageData,f as default};
